import pytest

from filingcopilot.execution import ResearchControl
from filingcopilot.models import ResearchAnswer, ResearchRequest
from filingcopilot.service import FilingCopilot
from filingcopilot.settings import Settings

# Integration, persistence, subprocess, or concurrency scope; included in full runs.
pytestmark = pytest.mark.slow


@pytest.mark.parametrize('question', [
    'PDD FY2025 公司的商业模式和主要收入来源是什么？',
    '收入增长来源是什么？', '利润变化与哪些经营因素有关？',
    'How is revenue generated by the business?', 'What is the quality of net income?',
    'PDD FY2025 公司资本投入主要用于什么？不要把所有投资当作现金资本开支。',
])
def test_qualitative_metric_question_is_not_answered_by_one_annual_number(tmp_path, question):
    service = FilingCopilot(Settings(home=tmp_path, embedding_mode='off'))
    plan = service.research_plan(ResearchRequest(question=question, ticker='PDD'))
    assert plan['annual_numeric_direct'] is False
    assert plan['uses_model'] is True


@pytest.mark.parametrize('question', ['PDD FY2025 营业收入', '净利润是多少？'])
def test_annual_number_query_keeps_deterministic_path(tmp_path, question):
    service = FilingCopilot(Settings(home=tmp_path, embedding_mode='off'))
    plan = service.research_plan(ResearchRequest(question=question, ticker='PDD'))
    assert plan['annual_numeric_direct'] is True


def test_research_plan_exposes_calls_latency_and_unknown_cost(tmp_path):
    service = FilingCopilot(Settings(home=tmp_path, embedding_mode="off"))
    plan = service.research_plan(
        ResearchRequest(question="苹果过去五年股价涨跌和最大回撤是多少？", ticker="AAPL")
    )
    budget = plan["budget"]
    assert budget["estimated_model_calls"] == 0
    assert budget["estimated_tool_calls"] >= 1
    assert budget["estimated_latency_seconds"] >= 0
    assert budget["estimated_cost_usd"] is None
    assert "FC_MODEL" in budget["cost_basis"]


def test_research_plan_estimates_agent_and_configured_cost(tmp_path):
    settings = Settings(
        home=tmp_path,
        embedding_mode="off",
        model_input_price_per_million=1.0,
        model_output_price_per_million=2.0,
    )
    service = FilingCopilot(settings)
    plan = service.research_plan(
        ResearchRequest(question="苹果股票怎么样？", ticker="AAPL", mode="agent")
    )
    budget = plan["budget"]
    assert plan["uses_model"] is True
    assert budget["estimated_model_calls"] >= 1
    assert budget["estimated_tool_calls"] > 1
    assert budget["estimated_cost_usd"] is not None
    assert budget["estimated_total_tokens"] == (
        budget["estimated_prompt_tokens"] + budget["estimated_completion_tokens"]
    )


def test_research_receipt_records_actual_budget_usage(tmp_path, monkeypatch):
    service = FilingCopilot(Settings(home=tmp_path, embedding_mode="off"))
    captured = {}

    def save_run(answer, package):
        captured["answer"] = answer

    service.corpus.save_run = save_run
    request = ResearchRequest(question="价格是多少？", ticker="AAPL", mode="reference")

    def fake_research(_request):
        answer = ResearchAnswer(
            id="run-budget",
            question=_request.question,
            as_of=_request.as_of,
            mode=_request.mode,
            status="answered",
            answer=[],
            gaps=[],
            evidence=[],
            trace=[{"stage": "tool", "tool": "get_stock_market", "duration_ms": 4}],
            usage={"model_calls": 0, "total_tokens": 0},
            elapsed_ms=1,
        )
        return answer, service.refresh_domain(), "AAPL"

    monkeypatch.setattr(service, "_research", fake_research)
    answer = service.research(request)
    assert answer.usage["tool_calls"] == 1
    assert answer.usage["model_calls"] == 0
    assert answer.usage["time_budget_seconds"] == service.settings.research_timeout
    assert answer.usage["budget_status"] == "completed"
    assert captured["answer"]["usage"]["tool_calls"] == 1


def test_control_records_tools_without_arguments():
    control = ResearchControl()
    control.record_tool("search_passages")
    control.record_tool("submit_answer")
    assert control.usage["tool_calls"] == 2
    assert control.usage["last_tool"] == "submit_answer"
